"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState, type FormEvent } from "react";

import { formatMXN } from "@/src/domain/sales/sale.entity";
import {
  loadStoreCheckout,
  type StoreCheckoutDraft,
} from "@/src/infrastructure/sales/store-checkout.storage";
import {
  loadStoreShipping,
  type StoreShippingAddress,
} from "@/src/infrastructure/sales/store-shipping.storage";
import { ModuleHero } from "@/src/presentation/components/ModuleHero";
import { PageShell } from "@/src/presentation/components/layout/PageShell";

type CardForm = {
  holder: string;
  number: string;
  expiry: string;
  cvv: string;
};

const initialCard: CardForm = {
  holder: "",
  number: "",
  expiry: "",
  cvv: "",
};

export default function StoreCardPaymentPage() {
  const router = useRouter();

  const [loaded, setLoaded] = useState(false);
  const [draft, setDraft] = useState<StoreCheckoutDraft | null>(null);
  const [shipping, setShipping] = useState<StoreShippingAddress | null>(null);
  const [card, setCard] = useState<CardForm>(initialCard);

  useEffect(() => {
    setDraft(loadStoreCheckout());
    setShipping(loadStoreShipping());
    setLoaded(true);
  }, []);

  const subtotal = draft?.subtotal ?? 0;
  const envio = Math.round(subtotal * 0.08 * 100) / 100;
  const total = (draft?.total ?? 0) + envio;

  function updateCard<K extends keyof CardForm>(
    field: K,
    value: CardForm[K],
  ) {
    setCard((previous) => ({
      ...previous,
      [field]: value,
    }));
  }

  function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!draft || !shipping) return;

    // Esta pantalla es una demostración: no procesa ni registra pagos.
    // No guardar los datos de tarjeta en el navegador.
    setCard(initialCard);
    router.push("/tienda/pago/confirmacion");
  }

  return (
    <PageShell>
      <main>
        <ModuleHero
          eyebrow="Tienda en línea · Checkout"
          title="Pago con tarjeta"
          description="Ingresa los datos de tu tarjeta para completar tu compra."        />

        <section data-tone="alt" className="vt-section">
          <div className="section-shell qt-grid">
            {!loaded ? (
              <div className="qf-card vt-loading">
                Cargando información del pedido...
              </div>
            ) : !draft || !shipping ? (
              <div className="qf-card vt-empty">
                <span className="eyebrow">Checkout incompleto</span>
                <h2 className="qa-title">Faltan datos de tu pedido</h2>
                <p className="qa-text">
                  Necesitamos un pedido y una dirección de envío antes de
                  continuar al pago.
                </p>
                <Link href="/tienda" className="btn btn-primary">
                  Volver a la tienda →
                </Link>
              </div>
            ) : (
              <>
                <form className="qf-card" onSubmit={handleSubmit}>
                  <span className="qf-group-label">
                    03 / Información de pago
                  </span>

                

                  <div className="qf-stack">
                    <label className="qf-field">
                      <span className="qf-label">Titular de la tarjeta *</span>
                      <input
                        className="qf-input"
                        autoComplete="off"
                        maxLength={100}
                        required
                        value={card.holder}
                        onChange={(event) =>
                          updateCard("holder", event.target.value)
                        }
                        placeholder="NOMBRE DEL TITULAR"
                      />
                    </label>

                    <label className="qf-field">
                      <span className="qf-label">Número de tarjeta *</span>
                      <input
                        className="qf-input"
                        inputMode="numeric"
                        autoComplete="off"
                        required
                        minLength={13}
                        maxLength={19}
                        pattern="[0-9 ]{13,19}"
                        title="Introduce entre 13 y 19 dígitos."
                        value={card.number}
                        onChange={(event) =>
                          updateCard(
                            "number",
                            event.target.value
                              .replace(/\D/g, "")
                              .slice(0, 16)
                              .replace(/(.{4})/g, "$1 ")
                              .trim(),
                          )
                        }
                        placeholder="0000 0000 0000 0000"
                      />
                    </label>

                    <div className="qf-row">
                      <label className="qf-field">
                        <span className="qf-label">
                          Vencimiento (MM/AA) *
                        </span>
                        <input
                          className="qf-input"
                          inputMode="numeric"
                          autoComplete="off"
                          required
                          pattern="(0[1-9]|1[0-2])\/[0-9]{2}"
                          title="Usa el formato MM/AA."
                          maxLength={5}
                          value={card.expiry}
                          onChange={(event) => {
                            const digits = event.target.value
                              .replace(/\D/g, "")
                              .slice(0, 4);

                            const value =
                              digits.length > 2
                                ? `${digits.slice(0, 2)}/${digits.slice(2)}`
                                : digits;

                            updateCard("expiry", value);
                          }}
                          placeholder="MM/AA"
                        />
                      </label>

                      <label className="qf-field">
                        <span className="qf-label">CVV *</span>
                        <input
                          className="qf-input"
                          type="password"
                          inputMode="numeric"
                          autoComplete="off"
                          required
                          pattern="[0-9]{3,4}"
                          title="Introduce 3 o 4 dígitos."
                          maxLength={4}
                          value={card.cvv}
                          onChange={(event) =>
                            updateCard(
                              "cvv",
                              event.target.value.replace(/\D/g, "").slice(0, 4),
                            )
                          }
                          placeholder="•••"
                        />
                      </label>
                    </div>
                  </div>

                  <div className="vt-pay-actions">
                    <button
                      type="button"
                      className="btn btn-ghost"
                      onClick={() => router.push("/tienda/pago/envio")}
                    >
                      ← Regresar
                    </button>

                    <button type="submit" className="btn btn-primary">
                      Continuar →
                    </button>
                  </div>
                </form>

                <aside className="qa-card vt-summary">
                  <span className="eyebrow">Resumen del pedido</span>

                  <div className="vt-stack">
                    {draft.items.map((item) => (
                      <div className="vt-summary-item" key={item.id}>
                        <div>
                          <p className="vt-summary-item-name">
                            {item.nombre}
                          </p>
                          <p className="vt-summary-item-qty">
                            {item.cantidad} × {formatMXN(item.precio)}
                          </p>
                        </div>
                        <span>
                          {formatMXN(item.precio * item.cantidad)}
                        </span>
                      </div>
                    ))}
                  </div>

                  <div className="vt-breakdown">
                    <div>
                      <span>Subtotal</span>
                      <span>{formatMXN(subtotal)}</span>
                    </div>
                    <div>
                      <span>IVA incluido</span>
                      <span>{formatMXN(draft.iva)}</span>
                    </div>
                    <div>
                      <span>Envío estimado (8%)</span>
                      <span>{formatMXN(envio)}</span>
                    </div>
                    <div className="vt-breakdown-total">
                      <span>Total estimado</span>
                      <span>{formatMXN(total)}</span>
                    </div>
                  </div>

                  <div className="vt-breakdown">
                    <span className="eyebrow">Dirección de entrega</span>
                    <p className="qa-text">
                      {shipping.recipient}
                      <br />
                      {shipping.street} {shipping.exteriorNumber}
                      {shipping.interiorNumber
                        ? `, Int. ${shipping.interiorNumber}`
                        : ""}
                      <br />
                      {shipping.neighborhood}, C. P. {shipping.zip}
                      <br />
                      {shipping.city}, {shipping.state}
                    </p>
                    <Link
                      href="/tienda/pago/envio"
                      className="btn btn-ghost"
                    >
                      Editar dirección
                    </Link>
                  </div>

                  <p className="vt-hint">
                    Demostración de frontend. El total es estimado; no se
                    valida el pago ni se realiza ningún cargo.
                  </p>
                </aside>
              </>
            )}
          </div>
        </section>
      </main>
    </PageShell>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { container } from "@/src/infrastructure/composition/root-container";
import { PageShell } from "@/src/presentation/components/layout/PageShell";

type PaginaProductoProps = {
  params: Promise<{ id: string }>;
};

async function obtenerProducto(id: string) {
  return container.products.getProductById(id);
}

export async function generateMetadata({
  params,
}: PaginaProductoProps): Promise<Metadata> {
  const { id } = await params;
  const producto = await obtenerProducto(id);

  if (!producto || producto.estado !== "activo") {
    return { title: "Producto no disponible | Marin Industries" };
  }

  const descripcion =
    producto.descripcion?.trim() ||
    `Consulta el precio y los detalles de ${producto.nombre} en Marin Industries.`;

  const imagen = producto.imagen;

  return {
    title: `${producto.nombre} | Marin Industries`,
    description: descripcion,
    openGraph: {
      title: producto.nombre,
      description: `${descripcion} Precio: $${producto.precio} MXN.`,
      type: "website",
      images: imagen ? [{ url: imagen, alt: producto.nombre }] : [],
    },
    twitter: {
      card: "summary_large_image",
      title: producto.nombre,
      description: descripcion,
      images: imagen ? [imagen] : [],
    },
  };
}

export default async function PaginaProducto({
  params,
}: PaginaProductoProps) {
  const { id } = await params;
  const producto = await obtenerProducto(id);

  if (!producto || producto.estado !== "activo") {
    notFound();
  }

  const precio = new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
  }).format(producto.precio);

  return (
    <PageShell>
      <main className="producto-publico">
        <div className="producto-publico__contenedor">
          <Link href="/tienda" className="producto-publico__volver">
            ← Ir a la tienda
          </Link>

          <article className="producto-publico__tarjeta">
            <div className="producto-publico__imagen">
              {producto.imagen ? (
                <img src={producto.imagen} alt={producto.nombre} />
              ) : (
                <span>Imagen no disponible</span>
              )}
            </div>

            <div className="producto-publico__contenido">
              <span className="eyebrow">
                MARIN INDUSTRIES / PRODUCTOS
              </span>

              <p className="producto-publico__categoria">
                {producto.categoria}
              </p>

              <h1>{producto.nombre}</h1>

              <p className="producto-publico__precio">{precio} MXN</p>

              <p className="producto-publico__descripcion">
                {producto.descripcion}
              </p>

              <Link
                href="/tienda"
                className="btn btn-primary"
              >
                Ir a la tienda
              </Link>

              <p className="producto-publico__nota">
                Ingeniería · Tecnología · Suministro
              </p>
            </div>
          </article>
        </div>
      </main>
    </PageShell>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { createSupabaseBrowserClient } from "@/src/infrastructure/supabase/client";

export function LogoutButton() {
  const router = useRouter();

  async function handleLogout() {
    const supabase = createSupabaseBrowserClient();

    const { error } = await supabase.auth.signOut();

    if (error) {
      console.error("Error al cerrar sesión:", error);
      return;
    }

    router.push("/");
    router.refresh();
  }

  return (
    <button
      type="button"
      onClick={handleLogout}
      className="border border-white/25 bg-white/10 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-white/20"
    >
      Cerrar sesión
    </button>
  );
}

"use client";

import { useEffect, useRef, useState, type ReactNode } from "react";
import type { CaseStudy } from "@/src/domain/marketing/landing-content.entity";
import { useLanguage } from "../../i18n/LanguageProvider";

type CaseAccordionProps = {
  studies: CaseStudy[];
  visuals: ReactNode[];
};

const pad = (n: number) => String(n).padStart(2, "0");

export function CaseAccordion({ studies, visuals }: CaseAccordionProps) {
  const { translations } = useLanguage();
  const copy = translations.home.caseStudies;
  const [active, setActive] = useState(0);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const last = studies.length - 1;

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    []
  );

  // Abrir al pasar el mouse (solo desktop con mouse), con pequeña pausa
  const hoverOpen = (i: number) => {
    if (!window.matchMedia("(hover: hover) and (min-width: 901px)").matches) return;
    if (timer.current) clearTimeout(timer.current);
    timer.current = setTimeout(() => setActive(i), 110);
  };

  const cancelHover = () => {
    if (timer.current) clearTimeout(timer.current);
  };

  const next = (i: number) => {
    if (i < last) {
      setActive(i + 1);
    } else {
      document
        .getElementById("contacto")
        ?.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  return (
    <div
      className="ca-track"
      onMouseLeave={cancelHover}
      onKeyDown={(e) => {
        if (e.key === "ArrowRight") setActive((a) => Math.min(last, a + 1));
        if (e.key === "ArrowLeft") setActive((a) => Math.max(0, a - 1));
      }}
    >
      {studies.map((s, i) => {
        const isActive = i === active;
        const translated = copy.items[s.id as keyof typeof copy.items];
        const title = translated?.title ?? s.title;
        const type = translated?.type ?? s.type;
        const sector = translated?.sector ?? s.sector;
        const description = translated?.copy ?? s.copy;
        const benefits = translated?.benefits ?? s.benefits;

        return (
          <article
            key={s.id}
            className="ca-panel"
            data-active={isActive}
            data-next={i === active + 1}
            onMouseEnter={() => hoverOpen(i)}
          >
            {/* Estado cerrado */}
            <button
              type="button"
              className="ca-collapsed"
              aria-expanded={isActive}
              aria-label={`${copy.openCase}: ${s.tag}, ${type}`}
              tabIndex={isActive ? -1 : 0}
              onClick={() => setActive(i)}
            >
              <span className="ca-num">{pad(i + 1)}</span>
              <span className="ca-vtag">
                {s.tag}
                <small>{s.type}</small>
              </span>
              <span className="ca-plus" aria-hidden="true">
                +
              </span>
            </button>

            {/* Estado abierto */}
            <div className="ca-open" inert={!isActive}>
              <div className="ca-open-inner">
                <div className="ca-visual">{s.img?.[0] ? <img src={s.img[0]} alt={title} /> : visuals[i]}</div>

                <div className="ca-info">
                  <div className="ca-meta">
                    <span className="ca-badge">{s.tag}</span>
                    <span>
                      {type} · {sector}
                    </span>
                  </div>

                  <h3 className="ca-h3">{title}</h3>
                  <p className="ca-copy">{description}</p>

                  <ul className="ca-benefits">
                    {benefits.map((b) => (
                      <li key={b}>
                        <svg
                          viewBox="0 0 24 24"
                          fill="none"
                          stroke="currentColor"
                          strokeWidth="2.2"
                          aria-hidden="true"
                        >
                          <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                        </svg>
                        {b}
                      </li>
                    ))}
                  </ul>

                  <div className="ca-foot">
                    <button
                      type="button"
                      className="btn btn-primary ca-next"
                      onClick={() => next(i)}
                    >
                      {i < last ? copy.next : copy.contact}
                      <span aria-hidden="true">{i < last ? "→" : "↓"}</span>
                    </button>
                    <span className="ca-count">
                      {pad(i + 1)} / {pad(studies.length)}
                    </span>
                  </div>
                </div>
              </div>
            </div>
          </article>
        );
      })}
    </div>
  );
}

"use client";

import type { LandingContent } from "@/src/domain/marketing/landing-content.entity";
import { useLanguage } from "../../i18n/LanguageProvider";

type InfoPanelProps = {
  services: LandingContent["services"];
  process: LandingContent["process"];
};

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
} from "react";

const TAB_IDS = ["servicios", "nosotros", "proceso"] as const;
const TAB_KEYS = ["services", "company", "process"] as const;

export function InfoPanel({ services, process }: InfoPanelProps) {
  const { translations } = useLanguage();
  const t = translations.home.infoPanel;
  type Pt = { x: number; y: number };
  type Layout = { anchor: Pt; slots: Pt[]; scale: number };

  function MediaSlot({
    label,
    ratio = "4 / 3",
  }: {
    label: string;
    ratio?: string;
  }) {
    return (
      <div className="media-slot" style={{ aspectRatio: ratio }}>
        <span>{label}</span>
      </div>
    );
  }

  const [active, setActive] = useState(0);
  const [layout, setLayout] = useState<Layout | null>(null);
  const [animate, setAnimate] = useState(false);

  const stageRef = useRef<HTMLDivElement>(null);
  const anchorRef = useRef<HTMLDivElement>(null);
  const labelRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const slotRefs = useRef<(HTMLSpanElement | null)[]>([]);
  const touchX = useRef<number | null>(null);

  const measure = useCallback(() => {
    const stage = stageRef.current;
    const anchor = anchorRef.current;
    const firstLabel = labelRefs.current[0];
    if (!stage || !anchor || !firstLabel) return;

    const st = stage.getBoundingClientRect();
    const an = anchor.getBoundingClientRect();
    const bigPx = parseFloat(getComputedStyle(firstLabel).fontSize);
    const smallPx = parseFloat(getComputedStyle(slotRefs.current[0]!).fontSize);

    setLayout({
      anchor: { x: an.left - st.left, y: an.top - st.top },
      slots: slotRefs.current.map((el) => {
        const r = el!.getBoundingClientRect();
        return { x: r.left - st.left, y: r.top - st.top };
      }),
      scale: smallPx / bigPx,
    });
  }, []);

  useLayoutEffect(() => {
    measure();
    const raf = requestAnimationFrame(() => setAnimate(true));
    document.fonts?.ready.then(measure);
    const ro = new ResizeObserver(measure);
    if (stageRef.current) ro.observe(stageRef.current);
    window.addEventListener("resize", measure);
    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, [measure]);

  // Los links del navbar (#servicios, #nosotros, #proceso) abren la pestaña correcta
  useEffect(() => {
    const openFromHash = (hash: string) => {
      const i = TAB_IDS.findIndex((id) => `#${id}` === hash);
      if (i >= 0) setActive(i);
    };

    // Al cargar la página con un hash (ej. /#nosotros)
    openFromHash(window.location.hash);

    // Al hacer clic en cualquier link a /#servicios, /#nosotros, /#proceso
    const onClick = (e: MouseEvent) => {
      const a = (e.target as HTMLElement).closest("a");
      if (!a) return;
      const url = new URL(a.href, window.location.origin);
      if (url.pathname === "/") openFromHash(url.hash);
    };

    document.addEventListener("click", onClick);
    return () => document.removeEventListener("click", onClick);
  }, []);

  const go = (i: number) =>
    setActive(Math.max(0, Math.min(TAB_IDS.length - 1, i)));

  return (
    <section id="empresa" data-tone="alt" className="pn-section relative">
      {" "}
      {TAB_IDS.map((id) => (
        <span key={id} id={id} className="pn-anchor" aria-hidden />
      ))}
      <div
        className="section-shell"
        onKeyDown={(e) => {
          const target = e.target as HTMLElement;

          if (
            target.matches("input, textarea, select, [contenteditable='true']")
          ) {
            return;
          }
          if (e.key === "ArrowRight") {
            e.preventDefault();
            go(active + 1);
          }

          if (e.key === "ArrowLeft") {
            e.preventDefault();
            go(active - 1);
          }
        }}
      >
        <div ref={stageRef} className="pn-stage">
          {/* Punto de anclaje del título (invisible, solo para medir) */}
          <div
            ref={anchorRef}
            className="pn-anchor-title pn-title-size"
            aria-hidden
          />

          {/* Etiquetas/títulos flotantes: son el mismo elemento en ambos estados */}
          {TAB_IDS.map((id, i) => {
            const isActive = i === active;
            const p = layout
              ? isActive
                ? layout.anchor
                : layout.slots[i]
              : { x: 0, y: 0 };
            const s = layout ? (isActive ? 1 : layout.scale) : 1;
            return (
              <span
                key={id}
                ref={(el) => {
                  labelRefs.current[i] = el;
                }}
                aria-hidden
                className="pn-label pn-title-size"
                data-active={isActive}
                data-animate={animate}
                style={{
                  transform: `translate(${p.x}px, ${p.y}px) scale(${s})`,
                  opacity: layout ? undefined : 0,
                }}
              >
                {t.tabs[TAB_KEYS[i]]}
              </span>
            );
          })}

          {/* Carrusel */}
          <div
            className="pn-viewport"
            onPointerDown={(e) => {
              if (e.pointerType !== "mouse") touchX.current = e.clientX;
            }}
            onPointerUp={(e) => {
              if (touchX.current === null) return;
              const dx = e.clientX - touchX.current;
              touchX.current = null;
              if (Math.abs(dx) > 50) go(active + (dx < 0 ? 1 : -1));
            }}
          >
            <div
              className="pn-track"
              style={{ transform: `translateX(-${active * 100}%)` }}
            >
              {/* 1 · Qué hacemos */}
              <div
                className="pn-slide"
                role="tabpanel"
                data-active={active === 0}
                inert={active !== 0}
              >
                <div className="pn-body grid items-center gap-12 lg:grid-cols-[1.1fr_0.9fr]">
                  <div>
                    <p className="mb-8 max-w-xl text-[var(--brand-text)]">
                      {t.services.intro}
                    </p>
                    <ul>
                      {services.map((s, n) => {
                        const localized =
                          t.services.items[
                            s.icon as keyof typeof t.services.items
                          ];
                        return (
                          <li key={s.icon} className="pn-row">
                            <span className="pn-row-n">
                              {String(n + 1).padStart(2, "0")}
                            </span>
                            <span className="pn-row-t">
                              {localized?.title ?? s.title}
                            </span>
                            <span className="pn-row-d">
                              {localized?.copy ?? s.copy}
                            </span>
                          </li>
                        );
                      })}
                    </ul>
                  </div>
                  <MediaSlot label={t.media.services} />
                </div>
              </div>

              {/* 2 · Quiénes somos */}
              <div
                className="pn-slide"
                role="tabpanel"
                data-active={active === 1}
                inert={active !== 1}
              >
                <div className="pn-body grid items-center gap-12 lg:grid-cols-[1.1fr_0.9fr]">
                  <div>
                    <p className="mb-5 max-w-xl text-[var(--brand-text)]">
                      {t.company.story}
                    </p>
                    <p className="mb-10 max-w-xl text-[var(--brand-text)]">
                      {t.company.purpose}
                    </p>
                    <div className="grid gap-4 sm:grid-cols-2">
                      <div className="card p-6">
                        <span className="eyebrow">
                          {t.company.missionLabel}
                        </span>
                        <p className="mt-3 text-sm text-[var(--brand-text)]">
                          {t.company.mission}
                        </p>
                      </div>
                      <div className="card p-6">
                        <span className="eyebrow">{t.company.visionLabel}</span>
                        <p className="mt-3 text-sm text-[var(--brand-text)]">
                          {t.company.vision}
                        </p>
                      </div>
                    </div>
                  </div>
                  <MediaSlot label={t.media.company} ratio="4 / 5" />
                </div>
              </div>

              {/* 3 · Cómo trabajamos */}
              <div
                className="pn-slide"
                role="tabpanel"
                data-active={active === 2}
                inert={active !== 2}
              >
                <div className="pn-body grid items-center gap-12 lg:grid-cols-[1.1fr_0.9fr]">
                  <div>
                    <p className="mb-8 max-w-xl text-[var(--brand-text)]">
                      {t.process.intro}
                    </p>
                    <ul>
                      {process.map((step, n) => {
                        const localized =
                          t.process.steps[
                            String(n + 1).padStart(
                              2,
                              "0",
                            ) as keyof typeof t.process.steps
                          ];
                        return (
                          <li key={step} className="pn-row">
                            <span className="pn-row-n">
                              {String(n + 1).padStart(2, "0")}
                            </span>
                            <span className="pn-row-t">
                              {localized?.title ?? step}
                            </span>
                            <span className="pn-row-d">
                              {localized?.description ?? ""}
                            </span>
                          </li>
                        );
                      })}
                    </ul>
                  </div>
                  <MediaSlot label={t.media.process} />
                </div>
              </div>
            </div>
          </div>

          {/* Fila de etiquetas: parece decoración, funciona como navegación */}
          <div
            className="pn-slots"
            role="tablist"
            aria-label={translations.common.sections}
          >
            {TAB_IDS.map((id, i) => (
              <button
                key={id}
                type="button"
                role="tab"
                aria-selected={i === active}
                onClick={() => go(i)}
                className="pn-slot"
                data-active={i === active}
              >
                <span
                  ref={(el) => {
                    slotRefs.current[i] = el;
                  }}
                  className="pn-slot-text"
                >
                  {t.tabs[TAB_KEYS[i]]}
                </span>
              </button>
            ))}
            <span className="pn-counter">
              {String(active + 1).padStart(2, "0")} /{" "}
              {String(TAB_IDS.length).padStart(2, "0")}
            </span>
          </div>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useLanguage } from "../../i18n/LanguageProvider";

const SECTION_IDS = ["inicio", "empresa", "casos", "contacto"] as const;

export function SectionRail() {
  const { translations } = useLanguage();
  const labels = translations.home.sectionRail.sections;
  const sections = SECTION_IDS.map((id) => ({ id, label: labels[id as keyof typeof labels] }));
  const [active, setActive] = useState(0);
  const [open, setOpen] = useState(false);
  const boxRef = useRef<HTMLDivElement>(null);

  // Scroll-spy: la sección activa es la última cuyo borde superior ya pasó el 40% de la pantalla
  useEffect(() => {
    let raf = 0;

    const update = () => {
      raf = 0;
      const line = window.innerHeight * 0.4;
      let current = 0;

      sections.forEach((s, i) => {
        const el = document.getElementById(s.id);
        if (el && el.getBoundingClientRect().top <= line) current = i;
      });

      setActive(current);
    };

    const onScroll = () => {
      if (!raf) raf = requestAnimationFrame(update);
    };

    update();
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("resize", onScroll);

    return () => {
      if (raf) cancelAnimationFrame(raf);
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("resize", onScroll);
    };
  }, []);

  // Menú móvil: cerrar con Escape o al tocar fuera
  useEffect(() => {
    if (!open) return;

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setOpen(false);
    };
    const onDown = (e: PointerEvent) => {
      if (!boxRef.current?.contains(e.target as Node)) setOpen(false);
    };

    window.addEventListener("keydown", onKey);
    window.addEventListener("pointerdown", onDown);

    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("pointerdown", onDown);
    };
  }, [open]);

  const goTo = (id: string) => {
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    document
      .getElementById(id)
      ?.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "start" });
    setOpen(false);
  };

  const pad = (n: number) => String(n).padStart(2, "0");

  return (
    <div ref={boxRef}>
      {/* Desktop: riel de marcas */}
      <nav className="rail" aria-label={translations.home.sectionRail.ariaLabel}>
        {sections.map((s, i) => (
          <button
            key={s.id}
            type="button"
            className="rail-item"
            data-active={i === active}
            aria-label={s.label}
            aria-current={i === active ? "true" : undefined}
            onClick={() => goTo(s.id)}
          >
            <span className="rail-label">{s.label}</span>
            <span className="rail-tick" />
          </button>
        ))}
      </nav>

      {/* Celular: botón índice */}
      <div className="rail-m">
        <button
          type="button"
          className="rail-m-btn"
          aria-expanded={open}
          aria-label={translations.home.sectionRail.mobileLabel}
          onClick={() => setOpen((o) => !o)}
        >
          {pad(active + 1)}
          <span>/{pad(sections.length)}</span>
        </button>

        <div className="rail-m-menu" data-open={open} inert={!open}>
          {sections.map((s, i) => (
            <button
              key={s.id}
              type="button"
              className="rail-m-item"
              data-active={i === active}
              onClick={() => goTo(s.id)}
            >
              <small>{pad(i + 1)}</small>
              {s.label}
            </button>
          ))}
        </div>
      </div>
    </div>
  );
}

"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useState } from "react";
import { ThemeToggle } from "./ThemeToggle";
import { useLanguage } from "../../i18n/LanguageProvider";

const navItems = [
  { label: "announcements", href: "/convocatorias" },
  { label: "services", href: "/servicios" },
  { label: "quotation", href: "/cotizacion" },
  { label: "humanResources", href: "/rh" },
  { label: "products", href: "/tienda" },
] as const;

export function Header() {
  const pathname = usePathname();
  const [open, setOpen] = useState(false);
  const { language, setLanguage, translations } = useLanguage();

  const isActive = (href: string) =>
    pathname === href || pathname.startsWith(`${href}/`);

  return (
    <header className="fixed left-0 top-0 z-50 w-full border-b border-brandLine bg-brandBg">
      <div className="section-shell flex items-center justify-between py-4">
        <Link href="/" className="flex items-center gap-4">
          <div className="h-10 w-10 overflow-hidden">
            <img
              src="/assets/logo.png"
              alt="Marin Industries Logo"
              className="h-full w-full object-cover"
            />
          </div>

          <span className="text-sm font-semibold tracking-tight text-brandDark">
            MARIN INDUSTRIES
          </span>
        </Link>

        <div className="flex items-center gap-4 lg:gap-6">
          <nav className="hidden items-center gap-8 text-sm font-medium lg:flex">
            {navItems.map((item) => {
              const esTienda = item.label === "products";

              return (
                <Link
                  key={item.href}
                  href={item.href}
                  target={esTienda ? "_blank" : undefined}
                  rel={esTienda ? "noopener noreferrer" : undefined}
                  aria-current={isActive(item.href) ? "page" : undefined}
                  className={`transition hover:text-brandAccent ${
                    isActive(item.href) ? "text-brandAccent" : "text-brandText"
                  }`}
                >
                  {translations.header.navigation[item.label]}
                </Link>
              );
            })}
          </nav>

          <ThemeToggle />
          <div
            className="flex items-center gap-1 rounded-md border border-brandLine p-1"
            aria-label={translations.language.select}
          >
            <button
              type="button"
              onClick={() => setLanguage("es")}
              aria-pressed={language === "es"}
              className={`rounded px-2 py-1 text-xs font-semibold transition ${
                language === "es"
                  ? "bg-brandAccent text-brandDark"
                  : "text-brandText hover:text-brandAccent"
              }`}
            >
              ES
            </button>

            <button
              type="button"
              onClick={() => setLanguage("en")}
              aria-pressed={language === "en"}
              className={`rounded px-2 py-1 text-xs font-semibold transition ${
                language === "en"
                  ? "bg-brandAccent text-brandDark"
                  : "text-brandText hover:text-brandAccent"
              }`}
            >
              EN
            </button>
          </div>

          <button
            type="button"
            className="lg:hidden"
            onClick={() => setOpen((prev) => !prev)}
            aria-label={
              open
                ? translations.header.closeMenu
                : translations.header.openMenu
            }
            aria-expanded={open}
          >
            <span className="block h-0.5 w-7 bg-brandDark" />
            <span className="mt-1.5 block h-0.5 w-7 bg-brandDark" />
            <span className="mt-1.5 block h-0.5 w-7 bg-brandDark" />
          </button>
        </div>
      </div>

      {open ? (
        <div className="border-t border-brandLine bg-brandBg px-6 py-4 lg:hidden">
          <nav className="flex flex-col gap-4 text-sm font-medium">
            {navItems.map((item) => (
              <Link
                key={item.href}
                href={item.href}
                onClick={() => setOpen(false)}
                className={`transition hover:text-brandAccent ${
                  isActive(item.href) ? "text-brandAccent" : "text-brandText"
                }`}
              >
                {translations.header.navigation[item.label]}
              </Link>
            ))}
          </nav>
        </div>
      ) : null}
    </header>
  );
}

"use client";

import type { Producto } from "./TarjetaProducto";
import { useLanguage } from "../../i18n/LanguageProvider";

type CarritoItemProps = {
  producto: Producto;
  cantidad: number;
  onCambiarCantidad: (cantidad: number) => void;
  onEliminar: () => void;
};

const moneda = (precio: number) =>
  new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
  }).format(precio);

export function CarritoItem({
  producto,
  cantidad,
  onCambiarCantidad,
  onEliminar,
}: CarritoItemProps) {
  const { translations } = useLanguage();
  const t = translations.store;
  return (
    <article className="carrito-item">
      <img className="carrito-item-imagen" src={producto.imagen} alt="" />
      <div className="carrito-item-info">
        <span className="producto-categoria">{producto.categoria}</span>
        <h3>{producto.nombre}</h3>
        <p>{moneda(producto.precio)} {t.perUnit}</p>
        <div className="carrito-item-controles">
          <div className="carrito-cantidad-control" aria-label={`${t.quantity} de ${producto.nombre}`}>
            <button
              type="button"
              aria-label={`${t.reduce} de ${producto.nombre}`}
              onClick={() => onCambiarCantidad(cantidad - 1)}
            >
              −
            </button>
            <span aria-live="polite">{cantidad}</span>
            <button
              type="button"
              aria-label={`${t.increase} de ${producto.nombre}`}
              disabled={cantidad >= producto.existencia}
              onClick={() => onCambiarCantidad(cantidad + 1)}
            >
              +
            </button>
          </div>
          <button
            type="button"
            className="carrito-item-eliminar"
            onClick={onEliminar}
          >
            {t.remove}
          </button>
        </div>
      </div>
      <strong className="carrito-item-total">
        {moneda(producto.precio * cantidad)}
      </strong>
    </article>
  );
}

"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { formatMXN, type SaleDraft } from "@/src/domain/sales/sale.entity";
import { loadSaleDraft } from "@/src/infrastructure/sales/sale-session.storage";

const steps = ["Venta", "Método de pago", "Datos de pago"];

export function CheckoutSteps({ current }: { current: 0 | 1 | 2 }) {
  return (
    <ol className="vt-steps" aria-label="Progreso de la venta">
      {steps.map((label, i) => (
        <li
          key={label}
          className="vt-step"
          data-state={i < current ? "done" : i === current ? "current" : "todo"}
          aria-current={i === current ? "step" : undefined}
        >
          <span className="vt-step-n">{String(i + 1).padStart(2, "0")}</span>
          <span className="vt-step-t">{label}</span>
        </li>
      ))}
    </ol>
  );
}

/** Carga la venta en curso guardada al confirmar en /ventas. */
export function useSaleDraft() {
  const [state, setState] = useState<{ loaded: boolean; draft: SaleDraft | null }>({
    loaded: false,
    draft: null,
  });

  useEffect(() => {
    setState({ loaded: true, draft: loadSaleDraft() });
  }, []);

  return state;
}

export function SaleSummary({ draft }: { draft: SaleDraft }) {
  return (
    <aside className="qa-card vt-summary" aria-label="Resumen de la venta">
      <span className="eyebrow">Resumen de la venta</span>
      <p className="vt-summary-folio">#{draft.folio}</p>

      <dl className="vt-summary-meta">
        <div><dt>Cliente</dt><dd>{draft.client.name}</dd></div>
        <div><dt>RFC</dt><dd className="font-mono">{draft.client.rfc}</dd></div>
        <div><dt>Sucursal</dt><dd>{draft.branch.name}</dd></div>
      </dl>

      <div className="vt-summary-item">
        <div>
          <p className="vt-summary-item-name">{draft.item.name}</p>
          <p className="vt-summary-item-qty">
            {draft.quantity} × {formatMXN(draft.item.unitPrice)}
          </p>
        </div>
        <span>{formatMXN(draft.subtotal)}</span>
      </div>

      <div className="vt-breakdown">
        <div><span>Subtotal</span><span>{formatMXN(draft.subtotal)}</span></div>
        <div><span>IVA (16%)</span><span>{formatMXN(draft.tax)}</span></div>
        <div className="vt-breakdown-total">
          <span>Total a cobrar</span>
          <span>{formatMXN(draft.total)}</span>
        </div>
      </div>
    </aside>
  );
}

