"use client";

import { useEffect, useRef, useState } from "react";
import type { Producto } from "./TarjetaProducto";
import { PlantillaProductoEditorial } from "./PlantillaProducto";

type CompartirProductoModalProps = {
  producto: Producto;
  onCerrar: () => void;
};

const moneda = (precio: number) =>
  new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
  }).format(precio);

export function CompartirProductoModal({
  producto,
  onCerrar,
}: CompartirProductoModalProps) {
  const plantillaRef = useRef<HTMLDivElement>(null);

  const [procesando, setProcesando] = useState(false);
  const [estado, setEstado] = useState("");
  const [enlace, setEnlace] = useState("");

  const texto = [
    producto.nombre,
    producto.descripcion,
    `Precio: ${moneda(producto.precio)} MXN`,
    "Conoce más en Marin Industries.",
  ].join("\n\n");

  useEffect(() => {
    setEnlace(
      `${window.location.origin}/tienda/producto/${encodeURIComponent(
        producto.id,
      )}`,
    );
  }, [producto.id]);

  useEffect(() => {
    const cerrarEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") onCerrar();
    };

    window.addEventListener("keydown", cerrarEscape);

    return () => {
      window.removeEventListener("keydown", cerrarEscape);
    };
  }, [onCerrar]);

  const generarImagen = async (): Promise<Blob> => {
    const contenedor = plantillaRef.current;

    if (!contenedor) {
      throw new Error("La vista previa no está disponible.");
    }

    const plantilla = contenedor.querySelector<HTMLElement>(
      ".editorial-producto",
    );

    if (!plantilla) {
      throw new Error("No se encontró la plantilla editorial.");
    }

    await document.fonts.ready;

    const imagenes = Array.from(
      plantilla.querySelectorAll<HTMLImageElement>("img"),
    );

    // Guardamos las URL originales para restaurarlas al terminar.
    const fuentesOriginales = imagenes.map((imagen) =>
      imagen.getAttribute("src"),
    );

    try {
      // Convertimos las imágenes remotas a datos locales para la captura.
      const fuentesData = await Promise.all(
        imagenes.map(async (imagen): Promise<string> => {
          const url = imagen.currentSrc || imagen.src;

          if (!url) {
            throw new Error("La imagen del producto no tiene una URL.");
          }

          if (url.startsWith("data:")) {
            return url;
          }

          const respuesta = await fetch(url, {
            mode: "cors",
            cache: "no-store",
          });

          if (!respuesta.ok) {
            throw new Error(
              `No se pudo descargar una imagen del producto (${respuesta.status}).`,
            );
          }

          const archivo = await respuesta.blob();

          return await new Promise<string>((resolve, reject) => {
            const lector = new FileReader();

            lector.onload = () => {
              if (typeof lector.result === "string") {
                resolve(lector.result);
              } else {
                reject(new Error("No se pudo preparar la imagen para el PNG."));
              }
            };

            lector.onerror = () => {
              reject(new Error("No se pudo leer la imagen del producto."));
            };

            lector.readAsDataURL(archivo);
          });
        }),
      );

      // La captura utilizará las imágenes convertidas, no las URL remotas.
      imagenes.forEach((imagen, indice) => {
        imagen.src = fuentesData[indice];
      });

      await Promise.all(
        imagenes.map(async (imagen) => {
          if (imagen.decode) {
            await imagen.decode();
          }
        }),
      );

      const { toCanvas } = await import("html-to-image");

      const dimensiones = plantilla.getBoundingClientRect();
      const fondoPlantilla = window.getComputedStyle(plantilla).backgroundColor;
      const ancho = dimensiones.width;
      const alto = dimensiones.height;

      if (!ancho || !alto) {
        throw new Error("La plantilla no tiene dimensiones visibles.");
      }

      const canvas = await toCanvas(plantilla, {
        width: ancho,
        height: alto,
        pixelRatio: 2,
        backgroundColor: fondoPlantilla,
        cacheBust: true,
      });

      const blob = await new Promise<Blob | null>((resolve) => {
        canvas.toBlob(resolve, "image/png");
      });

      if (!blob) {
        throw new Error("No se pudo convertir la vista previa a PNG.");
      }

      return blob;
    } finally {
      // Restauramos las URL originales, incluso si la captura falla.
      imagenes.forEach((imagen, indice) => {
        const fuenteOriginal = fuentesOriginales[indice];

        if (fuenteOriginal === null) {
          imagen.removeAttribute("src");
        } else {
          imagen.setAttribute("src", fuenteOriginal);
        }
      });
    }
  };

  const descargarBlob = (blob: Blob) => {
    const url = URL.createObjectURL(blob);
    const enlaceDescarga = document.createElement("a");

    enlaceDescarga.href = url;
    enlaceDescarga.download = `marin-${producto.id}-producto.png`;

    document.body.appendChild(enlaceDescarga);
    enlaceDescarga.click();
    enlaceDescarga.remove();

    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  const descargarImagen = async () => {
    setProcesando(true);
    setEstado("");

    try {
      const blob = await generarImagen();
      descargarBlob(blob);
      setEstado("Imagen PNG generada y descargada.");
    } catch (error) {
      setEstado(
        error instanceof Error
          ? error.message
          : "No se pudo generar la imagen.",
      );
    } finally {
      setProcesando(false);
    }
  };

  const copiarTexto = async () => {
    if (!enlace) {
      setEstado("El enlace del producto todavía no está disponible.");
      return;
    }

    try {
      await navigator.clipboard.writeText(`${texto}\n\n${enlace}`);
      setEstado("Texto comercial y enlace copiados.");
    } catch {
      setEstado("No se pudo copiar el texto en este navegador.");
    }
  };

  const copiarEnlace = async () => {
    if (!enlace) {
      setEstado("El enlace del producto todavía no está disponible.");
      return;
    }

    try {
      await navigator.clipboard.writeText(enlace);
      setEstado("Enlace del producto copiado.");
    } catch {
      setEstado(
        "No se pudo copiar el enlace. Intenta desde una conexión segura.",
      );
    }
  };

  const compartirDispositivo = async () => {
    setProcesando(true);
    setEstado("");

    try {
      const blob = await generarImagen();
      const archivo = new File([blob], `marin-${producto.id}-producto.png`, {
        type: "image/png",
      });

      if (navigator.share && navigator.canShare?.({ files: [archivo] })) {
        await navigator.share({
          title: producto.nombre,
          text: `${texto}\n\n${enlace}`,
          files: [archivo],
        });

        setEstado("Se abrió el menú para compartir.");
      } else {
        descargarBlob(blob);

        if (enlace) {
          await navigator.clipboard.writeText(`${texto}\n\n${enlace}`);
          setEstado(
            "Imagen descargada y texto copiado. Adjunta la imagen en la aplicación deseada.",
          );
        } else {
          setEstado(
            "Imagen descargada. Comparte el texto y el enlace cuando estén disponibles.",
          );
        }
      }
    } catch (error) {
      if (error instanceof Error && error.name === "AbortError") {
        setEstado("Se canceló el menú de compartir.");
      } else {
        setEstado(
          error instanceof Error
            ? error.message
            : "No se pudo compartir el producto.",
        );
      }
    } finally {
      setProcesando(false);
    }
  };

  const abrirRedSocial = (red: "facebook" | "x" | "whatsapp") => {
    if (!enlace) {
      setEstado("El enlace del producto todavía no está disponible.");
      return;
    }

    const destinos = {
      facebook: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(
        enlace,
      )}`,
      x: `https://twitter.com/intent/tweet?text=${encodeURIComponent(
        `${producto.nombre} — ${moneda(producto.precio)} MXN`,
      )}&url=${encodeURIComponent(enlace)}`,
      whatsapp: `https://wa.me/?text=${encodeURIComponent(
        `${texto}\n\n${enlace}`,
      )}`,
    };

    window.open(destinos[red], "_blank", "noopener,noreferrer");
  };

  return (
    <div
      className="tienda-overlay"
      onMouseDown={(event) => {
        if (event.target === event.currentTarget) onCerrar();
      }}
    >
      <section
        className="compartir-producto-modal"
        role="dialog"
        aria-modal="true"
        aria-labelledby="compartir-producto-titulo"
      >
        <header className="compartir-producto-modal__header">
          <div>
            <span className="eyebrow">MARIN INDUSTRIES / SOCIAL ASSETS</span>

            <h2 id="compartir-producto-titulo">Compartir producto</h2>

            <p>{producto.nombre}</p>
          </div>

          <button
            type="button"
            className="compartir-producto-modal__cerrar"
            aria-label="Cerrar"
            onClick={onCerrar}
          >
            ×
          </button>
        </header>

        <div className="compartir-producto-modal__preview">
          <div className="compartir-producto-modal__lienzo">
            <div ref={plantillaRef}>
              <PlantillaProductoEditorial producto={producto} />
            </div>
          </div>
        </div>

        <footer className="compartir-producto-modal__acciones">
          <button
            type="button"
            className="btn btn-primary"
            disabled={procesando}
            onClick={descargarImagen}
          >
            {procesando ? "Procesando..." : "Descargar PNG"}
          </button>

          <button
            type="button"
            className="btn btn-ghost"
            disabled={procesando}
            onClick={compartirDispositivo}
          >
            Compartir imagen
          </button>

          <button
            type="button"
            className="btn btn-ghost"
            disabled={!enlace || procesando}
            onClick={copiarTexto}
          >
            Copiar texto
          </button>

          <button
            type="button"
            className="btn btn-ghost"
            disabled={!enlace || procesando}
            onClick={() => abrirRedSocial("whatsapp")}
          >
            WhatsApp
          </button>

          <button
            type="button"
            className="btn btn-ghost"
            disabled={!enlace || procesando}
            onClick={() => abrirRedSocial("facebook")}
          >
            Facebook
          </button>

          <button
            type="button"
            className="btn btn-ghost"
            disabled={!enlace || procesando}
            onClick={() => abrirRedSocial("x")}
          >
            X
          </button>

          <button
            type="button"
            className="btn btn-ghost"
            disabled={!enlace || procesando}
            onClick={copiarEnlace}
          >
            Copiar enlace
          </button>

          {estado && (
            <p
              className="compartir-producto-modal__estado"
              role="status"
              aria-live="polite"
            >
              {estado}
            </p>
          )}
        </footer>
      </section>
    </div>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { TarjetaProducto, type Producto } from "./TarjetaProducto";
import { CarritoItem } from "./CarritoItem";

import { CompartirProductoModal } from "./CompartirProductoModal";

const CARRITO_STORAGE_KEY = "marin.store.cart";
const TASA_IVA = 0.16;



import { container } from "@/src/infrastructure/composition/root-container";
import { productosEstaticos } from "@/src/infrastructure/products/static-product.repository";

import { useRouter } from "next/navigation";
import { saveStoreCheckout } from "@/src/infrastructure/sales/store-checkout.storage";
import { useLanguage } from "../../i18n/LanguageProvider";

const moneda = (precio: number) =>
  new Intl.NumberFormat("es-MX", {
    style: "currency",
    currency: "MXN",
  }).format(precio);

type GridProductosProps = {
  productosInicialesProp?: Producto[];
};

export function GridProductos({
  productosInicialesProp,
}: GridProductosProps = {}) {
  const { translations } = useLanguage();
  const t = translations.store;
  const [productos, setProductos] = useState<Producto[]>(
    productosInicialesProp && productosInicialesProp.length > 0
      ? productosInicialesProp
      : productosEstaticos,
  );

  const [cargando, setCargando] = useState(false);
  const [busqueda, setBusqueda] = useState("");
  const [categoria, setCategoria] = useState("Todas");
  const [soloOfertas, setSoloOfertas] = useState(false);
  const [productoExpandido, setProductoExpandido] = useState<string | null>(
    null,
  );
  const [carrito, setCarrito] = useState<Record<string, number>>({});
  const [carritoAbierto, setCarritoAbierto] = useState(false);
  const [carritoCargado, setCarritoCargado] = useState(false);
  const router = useRouter();

  const [productoParaCompartir, setProductoParaCompartir] =
  useState<Producto | null>(null);

  // Cargar productos desde la base de datos (Supabase o respaldo estático)
  useEffect(() => {
    let activo = true;
    setCargando(true);
    container.products
      .listProducts({ soloActivos: true })
      .then((items) => {
        if (activo && items.length > 0) {
          setProductos(items);
        }
      })
      .catch((err) => {
        console.warn(
          "No se pudieron cargar productos de la base de datos:",
          err,
        );
      })
      .finally(() => {
        if (activo) setCargando(false);
      });

    return () => {
      activo = false;
    };
  }, []);

  useEffect(() => {
    try {
      const guardado = window.localStorage.getItem(CARRITO_STORAGE_KEY);
      if (guardado) {
        const cantidades = JSON.parse(guardado) as Record<string, number>;
        setCarrito(
          Object.fromEntries(
            Object.entries(cantidades).filter(
              ([id, cantidad]) =>
                productos.some((producto) => producto.id === id) &&
                Number.isInteger(cantidad) &&
                cantidad > 0,
            ),
          ),
        );
      }
    } catch {
      window.localStorage.removeItem(CARRITO_STORAGE_KEY);
    }
    setCarritoCargado(true);
  }, [productos]);

  useEffect(() => {
    if (!carritoCargado) return;

    try {
      window.localStorage.setItem(CARRITO_STORAGE_KEY, JSON.stringify(carrito));
    } catch {}
  }, [carrito, carritoCargado]);

  useEffect(() => {
    const cerrarConEscape = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setProductoExpandido(null);
        setCarritoAbierto(false);
      }
    };

    window.addEventListener("keydown", cerrarConEscape);
    return () => window.removeEventListener("keydown", cerrarConEscape);
  }, []);

  const categorias = useMemo(
    () => [
      "Todas",
      ...new Set(productos.map((producto) => producto.categoria)),
    ],
    [productos],
  );

  const productosFiltrados = useMemo(() => {
    const termino = busqueda.trim().toLowerCase();

    return productos.filter((producto) => {
      const coincideTexto =
        producto.nombre.toLowerCase().includes(termino) ||
        producto.descripcion.toLowerCase().includes(termino);

      const coincideCategoria =
        categoria === "Todas" || producto.categoria === categoria;

      const coincideOferta = !soloOfertas || producto.oferta === true;

      return coincideTexto && coincideCategoria && coincideOferta;
    });
  }, [productos, busqueda, categoria, soloOfertas]);

  const totalArticulos = Object.values(carrito).reduce(
    (total, cantidad) => total + cantidad,
    0,
  );
  const articulosCarrito = productos.flatMap((producto) => {
    const cantidad = carrito[producto.id] ?? 0;
    return cantidad > 0 ? [{ producto, cantidad }] : [];
  });
  const subtotal = articulosCarrito.reduce(
    (total, articulo) => total + articulo.producto.precio * articulo.cantidad,
    0,
  );
  const iva = subtotal * TASA_IVA;
  const total = subtotal + iva;

  const agregarAlCarrito = (producto: Producto) => {
    setCarrito((actual) => {
      const cantidadActual = actual[producto.id] ?? 0;

      if (cantidadActual >= producto.existencia) {
        return actual;
      }

      return {
        ...actual,
        [producto.id]: cantidadActual + 1,
      };
    });
  };

  const actualizarCantidad = (producto: Producto, cantidad: number) => {
    setCarrito((actual) => {
      const siguiente = { ...actual };
      if (cantidad <= 0) {
        delete siguiente[producto.id];
      } else {
        siguiente[producto.id] = Math.min(cantidad, producto.existencia);
      }
      return siguiente;
    });
  };

  const productoSeleccionado = productos.find(
    (producto) => producto.id === productoExpandido,
  );

  return (
    <section className="tienda-section">
      <div className="section-shell">
        <header className="tienda-encabezado">
          <div>
            <span className="eyebrow">MARIN INDUSTRIES / {t.catalog.toUpperCase()}</span>
            <h1 className="tienda-titulo">{t.catalog}</h1>
            <p className="tienda-descripcion">
              {t.description}
            </p>
          </div>

          <button
            type="button"
            className="btn btn-primary tienda-carrito"
            onClick={() => setCarritoAbierto(true)}
            aria-label={`${t.viewCart}, ${totalArticulos} ${t.articles}`}
          >
            {t.cart}{" "}
            <span className="tienda-carrito-cantidad">{totalArticulos}</span>
          </button>
        </header>

        <div className="tienda-controles">
          <label className="tienda-busqueda">
            <span>{t.search}</span>
            <input
              type="search"
              value={busqueda}
              onChange={(event) => setBusqueda(event.target.value)}
              placeholder={t.searchPlaceholder}
            />
          </label>

          <label className="tienda-categoria">
            <span>{t.category}</span>
            <select
              value={categoria}
              onChange={(event) => setCategoria(event.target.value)}
            >
              {categorias.map((nombre) => (
                <option key={nombre} value={nombre}>
                  {nombre}
                </option>
              ))}
            </select>
          </label>

          <button
            type="button"
            className={`btn ${soloOfertas ? "btn-primary" : "btn-ghost"}`}
            aria-pressed={soloOfertas}
            onClick={() => setSoloOfertas((actual) => !actual)}
          >
            {soloOfertas ? t.showAll : t.offers}
          </button>
        </div>

        {productosFiltrados.length > 0 ? (
          <div className="productos-grid">
            {productosFiltrados.map((producto) => (
              <TarjetaProducto
                key={producto.id}
                producto={producto}
                onExpandir={() => setProductoExpandido(producto.id)}
                onAgregarCarrito={agregarAlCarrito}
                onVerCarrito={() => setCarritoAbierto(true)}
                onCompartir={setProductoParaCompartir}
              />
            ))}
          </div>
        ) : (
          <p className="tienda-vacio">
            {t.emptyResults}
          </p>
        )}

        <footer className="tienda-pie">
          <span>{productosFiltrados.length} {t.productsFound}</span>
          <Link href="/cotizacion">{t.requestQuote}</Link>
        </footer>
      </div>

      {productoSeleccionado && (
        <div
          className="tienda-overlay"
          onClick={() => setProductoExpandido(null)}
        >
          <section
            className="producto-dialogo"
            role="dialog"
            aria-modal="true"
            aria-label={`${t.details} ${productoSeleccionado.nombre}`}
            onClick={(event) => event.stopPropagation()}
          >
            <button
              type="button"
              className="tienda-modal-cerrar"
              aria-label={t.closeDetails}
              onClick={() => setProductoExpandido(null)}
            >
              ×
            </button>
            <TarjetaProducto
              producto={productoSeleccionado}
              expandida
              onExpandir={() => {}}
              onAgregarCarrito={agregarAlCarrito}
              onCerrar={() => setProductoExpandido(null)}
              onVerCarrito={() => {
                setProductoExpandido(null);
                setCarritoAbierto(true);
              }}
              onCompartir={setProductoParaCompartir}
            />
          </section>
        </div>
      )}

      {productoParaCompartir && (
        <CompartirProductoModal
          producto={productoParaCompartir}
          onCerrar={() => setProductoParaCompartir(null)}
        />
      )}

      {carritoAbierto && (
        <div
          className="tienda-overlay"
          onClick={() => setCarritoAbierto(false)}
        >
          <section
            className="carrito-dialogo"
            role="dialog"
            aria-modal="true"
            aria-labelledby="carrito-titulo"
            onClick={(event) => event.stopPropagation()}
          >
            <header className="carrito-encabezado">
              <div>
                <span className="eyebrow">{t.order}</span>
                <h2 id="carrito-titulo">{t.cart}</h2>
                <p>{totalArticulos} {t.articles}</p>
              </div>
              <button
                type="button"
                className="tienda-modal-cerrar"
                aria-label={t.closeCart}
                onClick={() => setCarritoAbierto(false)}
              >
                ×
              </button>
            </header>

            {articulosCarrito.length > 0 ? (
              <div className="carrito-cuerpo">
                <div
                  className="carrito-articulos"
                  aria-label={t.cartItems}
                >
                  {articulosCarrito.map(({ producto, cantidad }) => (
                    <CarritoItem
                      key={producto.id}
                      producto={producto}
                      cantidad={cantidad}
                      onCambiarCantidad={(nuevaCantidad) =>
                        actualizarCantidad(producto, nuevaCantidad)
                      }
                      onEliminar={() => actualizarCantidad(producto, 0)}
                    />
                  ))}
                </div>

                <aside
                  className="carrito-resumen"
                  aria-label={t.priceSummary}
                >
                  <h3>{t.summary}</h3>
                  <dl>
                    <div>
                      <dt>{t.subtotal}</dt>
                      <dd>{moneda(subtotal)}</dd>
                    </div>
                    <div>
                      <dt>{t.tax}</dt>
                      <dd>{moneda(iva)}</dd>
                    </div>
                    <div className="carrito-total">
                      <dt>{t.total}</dt>
                      <dd>{moneda(total)}</dd>
                    </div>
                  </dl>
                  <button
                    type="button"
                    className="btn btn-ghost carrito-vaciar"
                    onClick={() => setCarrito({})}
                  >
                    {t.clear}
                  </button>
                  <button
                    type="button"
                    className="btn btn-primary carrito-continuar"
                    disabled={articulosCarrito.length === 0}
                    onClick={() => {
                      if (articulosCarrito.length === 0) return;

                      saveStoreCheckout({
                        items: articulosCarrito.map(
                          ({ producto, cantidad }) => ({
                            id: producto.id,
                            nombre: producto.nombre,
                            precio: producto.precio,
                            cantidad,
                          }),
                        ),
                        subtotal,
                        iva,
                        total,
                      });

                      setCarritoAbierto(false);
                      router.push("/tienda/pago");
                    }}
                  >
                    {t.checkout}
                  </button>
                  <button
                    type="button"
                    className="btn btn-primary carrito-continuar"
                    onClick={() => setCarritoAbierto(false)}
                  >
                    {t.continue}
                  </button>
                </aside>
              </div>
            ) : (
              <div className="carrito-vacio">
                <p>{t.emptyCart}</p>
                <button
                  type="button"
                  className="btn btn-primary"
                  onClick={() => setCarritoAbierto(false)}
                >
                  {t.explore}
                </button>
              </div>
            )}
          </section>
        </div>
      )}
    </section>
  );
}

