}: ShippingFormProps) {
  const [address, setAddress] =
    useState<StoreShippingAddress>(initialAddress);

  function update<K extends keyof StoreShippingAddress>(
    field: K,
    value: StoreShippingAddress[K],
  ) {
    setAddress((previous) => ({
